function fixture(options={}){let evaluations=0,detach=0,dispose=0,elementDispose=0,conversions=0,acquisitions=0,counts=0,sent,callback;const handle={evaluate:async()=>structuredClone(evaluations++?options.after??state:state),dispose:async()=>{elementDispose++;}},raw={evaluate:(...args)=>handle.evaluate(...args),asElement:()=>{conversions++;if(Object.hasOwn(options,'conversionError'))throw options.conversionError;return Object.hasOwn(options,'element')?options.element:handle;},dispose:async()=>{dispose++;if(Object.hasOwn(options,'disposeError'))throw options.disposeError;}},session={send:async(method,args)=>{sent={method,args};if(Object.hasOwn(options,'primary'))throw options.primary;return options.sendPromise??{data:options.data??png().toString('base64')};},detach:async()=>{detach++;if(Object.hasOwn(options,'detachError'))throw options.detachError;return options.detachPromise;}};return {handle,raw,session,page:{locator:()=>({count:async()=>{counts++;return options.count??1;}}),evaluateHandle:fn=>{acquisitions++;callback=fn;if(Object.hasOwn(options,'count'))runInNewContext('('+fn.toString()+')()',browserWorld(options.count===0?'missing':options.count===1?'valid':'duplicate').context);return options.handlePromise??Promise.resolve(raw);},context:()=>({newCDPSession:()=>options.sessionPromise??Promise.resolve(session)})},stats:()=>({detach,dispose,elementDispose,conversions,acquisitions,counts,sent,callback})};}
