    const s=storage(),f=fixture(),world=browserWorld(),acquire=f.page.evaluateHandle;let phase=initial,counts=0,attempts=0;
    world.context.document.querySelectorAll=selector=>{assert.equal(selector,'.cc-pixi-stage canvas');return phase==='missing'?[]:phase==='duplicate'?[world.node,world.node]:[world.node];};
    assert.equal(world.context.document.querySelectorAll('.cc-pixi-stage canvas').length,initial==='missing'?0:initial==='duplicate'?2:1);
    f.page.locator=selector=>({count:async()=>{counts++;return world.context.document.querySelectorAll(selector).length;}});
    f.page.evaluateHandle=fn=>{attempts++;phase=atAcquisition;assertAcquiredEnvelope(inBrowser(fn,world.context),world.node);return acquire(fn);};
